const state = {items: [], index: -1, shuffle: false, repeat: "off", objectUrls: new Set(), selected: -1, native: null, fallbacking: false, playbackToken: 0, youtubeState: -1, youtubeTime: 0, youtubeDuration: 0, epgNames: new Map(), programmes: [], abStart: null, abEnd: null, abToken: -1, rateIndex: 2, view: "now", expanded: new Set(), multi: new Set()};
const VIEWS = {now: () => true, files: item => !!item.file, streams: item => !item.file && (!!item.url && !item.kind?.startsWith("casu") && item.kind !== "youtube" && item.kind !== "spotify"), playlists: item => !!(item.epgId || item.group || item.logo), iptv: item => !!item.epgId, youtube: item => item.kind === "youtube", spotify: item => item.kind === "spotify", casu: item => (item.kind || "").startsWith("casu")};
