const formatTime = seconds => { if(!Number.isFinite(seconds)) return "LIVE"; const s=Math.max(0,Math.floor(seconds)); return `${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`; };
