function youtubeId(value){try{const u=new URL(value),host=u.hostname.toLowerCase().replace(/\.$/,"");let id=null;if(host==="youtu.be"||host.endsWith(".youtu.be"))id=u.pathname.slice(1).split("/")[0];if(host==="youtube.com"||host.endsWith(".youtube.com"))id=u.searchParams.get("v")||(u.pathname.match(/^\/(?:shorts|embed)\/([^/?#]+)/)?.[1]||null);return /^[A-Za-z0-9_-]{11}$/.test(id||"")?id:null}catch{}return null}
const NETWORK_SCHEMES=new Set(["http:","https:","ftp:","ftps:","rtsp:","rtsps:","rtmp:","rtmps:","rtp:","udp:","srt:","rist:","smb:","mmsh:","mmst:"]);
const MAX_PLAYLIST_BYTES=8*1024*1024,MAX_PLAYLIST_ENTRIES=10000,MAX_PLAYLIST_LINE=4096;
