function itemLabel(item){return item.title || item.file?.name || new URL(item.url).hostname}
function renderQueue(){const query=$("#search").value.trim().toLowerCase(),viewFilter=VIEWS[state.view]||VIEWS.now;queueNode.replaceChildren();let shown=0,lastPlaylist=null;state.items.forEach((item,index)=>{if(!viewFilter(item))return;if(query&&!itemLabel(item).toLowerCase().includes(query))return;shown++;if(item.playlist&&!query){if(lastPlaylist!==item.playlist){lastPlaylist=item.playlist;const open=state.expanded.has(item.playlist),count=state.items.filter(entry=>entry.playlist===item.playlist&&viewFilter(entry)).length;const header=document.createElement("li");header.className="queue-group"+(open?" open":"");header.dataset.group=item.playlist;header.innerHTML=`<span class="thumb">☷</span><span class="track"><strong></strong><small></small></span>`;header.querySelector("strong").textContent=item.playlist;header.querySelector("small").textContent=`PLAYLIST · ${count} entries · click to ${open?"collapse":"expand"}`;header.onclick=()=>{open?state.expanded.delete(item.playlist):state.expanded.add(item.playlist);renderQueue()};const tools=document.createElement("span");tools.className="item-tools";const pb=document.createElement("button");pb.type="button";pb.textContent="▶";pb.title="Play playlist from the start";pb.onclick=e=>{e.stopPropagation();playPlaylistGroup(item.playlist)};const ub=document.createElement("button");ub.type="button";ub.textContent="↑";ub.title="Move playlist up";ub.onclick=e=>{e.stopPropagation();movePlaylistGroup(item.playlist,-1)};const db=document.createElement("button");db.type="button";db.textContent="↓";db.title="Move playlist down";db.onclick=e=>{e.stopPropagation();movePlaylistGroup(item.playlist,1)};const rb=document.createElement("button");rb.type="button";rb.textContent="×";rb.title="Remove playlist from the queue";rb.onclick=e=>{e.stopPropagation();removePlaylistGroup(item.playlist)};tools.append(pb,ub,db,rb);header.append(tools);queueNode.append(header)}if(!state.expanded.has(item.playlist))return}else{lastPlaylist=null}const li=document.createElement("li");li.dataset.index=index;const multi=state.multi.has(item);li.className=(index===state.index?"active":"")+(multi?" multi":"");li.setAttribute("aria-current",index===state.index?"true":"false");li.innerHTML=`<span class="thumb">${item.kind==="audio"?"♫":item.kind?.startsWith("casu")?"◆":"▶"}</span><span class="track"><strong></strong><small></small></span>`;li.querySelector("strong").textContent=itemLabel(item);li.querySelector("small").textContent=(item.kind||"media").toUpperCase()+(item.playlist?" · "+item.playlist:"");const tools=document.createElement("span");tools.className="item-tools";const rn=document.createElement("button");rn.type="button";rn.textContent="✎";rn.title="Rename";rn.onclick=e=>{e.stopPropagation();renameIndex(index)};const rm=document.createElement("button");rm.type="button";rm.textContent="×";rm.title="Remove";rm.onclick=e=>{e.stopPropagation();removeIndex(index)};tools.append(rn,rm);li.append(tools);li.onclick=event=>{if(event.ctrlKey||event.shiftKey){multi?state.multi.delete(item):state.multi.add(item);renderQueue();return}playIndex(index)};li.onfocus=()=>state.selected=index;li.onkeydown=event=>{if(event.key==="Enter"){event.preventDefault();playIndex(index)}};li.tabIndex=0;queueNode.append(li);if(index===state.index)li.scrollIntoView({block:"nearest"})});$("#queue-summary").textContent=`${shown}/${state.items.length} item${state.items.length===1?"":"s"}${state.multi.size?` · ${state.multi.size} marked (Esc clears)`:``}`}
function addItem(item){state.items.push(item);if(!(VIEWS[state.view]||VIEWS.now)(item)){state.view="now";markNav()}renderQueue();if(state.index<0)playIndex(0);return item}

