function stopAll(){++state.playbackToken;media.pause();media.removeAttribute("src");media.load();stopYoutube();stopNative()}
function rowOf(index){const item=state.items[index];if(!item)return null;if(item.playlist){let start=index;while(start>0&&state.items[start-1]?.playlist===item.playlist)start--;let end=index;while(end+1<state.items.length&&state.items[end+1]?.playlist===item.playlist)end++;return{start,end,group:true,name:item.playlist}}return{start:index,end:index,group:false}}
function selectedRows(){const rows=[];if(state.multi.size){for(let i=0;i<state.items.length;i++){if(!state.multi.has(state.items[i]))continue;const row=rowOf(i);if(!rows.some(r=>i>=r.start&&i<=r.end))rows.push(row)}return rows}const sel=state.selected>=0?state.selected:state.index;return sel>=0?[rowOf(sel)]:[]}
function moveRowSegment(start,delta){const row=rowOf(start);if(!row)return;if(delta>0){if(row.end+1>=state.items.length)return;const removed=state.items.splice(row.start,row.end-row.start+1);const below=rowOf(row.start);state.items.splice(below.end+1,0,...removed)}else{if(row.start<=0)return;const removed=state.items.splice(row.start,row.end-row.start+1);const above=rowOf(row.start-1);state.items.splice(above.start,0,...removed)}}
function moveRows(delta){const rows=selectedRows();if(!rows.length)return;const playing=state.items[state.index],starts=rows.map(r=>r.start).sort((a,b)=>a-b);if(delta>0){for(let i=starts.length-1;i>=0;i--)moveRowSegment(starts[i],1)}else{for(let i=0;i<starts.length;i++)moveRowSegment(starts[i],-1)}state.index=playing?state.items.indexOf(playing):-1;if(state.selected>=0)state.selected=playing?state.items.indexOf(playing):-1;renderQueue()}
function removeRows(){const rows=selectedRows();if(!rows.length)return;const playing=state.items[state.index],doomed=new Set();for(const row of rows)for(let i=row.start;i<=row.end;i++)doomed.add(state.items[i]);state.items=state.items.filter(item=>!doomed.has(item));state.multi=new Set(state.items.filter(item=>state.multi.has(item)));state.index=playing&&doomed.has(playing)?-1:(playing?state.items.indexOf(playing):-1);if(state.index<0)stopAll();renderQueue()}
function movePlaylistGroup(name,delta){const item=state.items.find(e=>e.playlist===name);if(!item)return;const row=rowOf(state.items.indexOf(item));moveRowSegment(row.start,delta);const playing=state.items[state.index];state.index=playing?state.items.indexOf(playing):-1;renderQueue()}
function removePlaylistGroup(name){const playing=state.items[state.index],members=state.items.filter(e=>e.playlist===name);if(!members.length)return;state.items=state.items.filter(e=>e.playlist!==name);members.forEach(releaseItem);state.multi=new Set(state.items.filter(item=>state.multi.has(item)));state.index=playing&&playing.playlist===name?-1:(playing?state.items.indexOf(playing):-1);if(state.index<0)stopAll();renderQueue()}
function playPlaylistGroup(name){const index=state.items.findIndex(e=>e.playlist===name);if(index>=0)playIndex(index)}
function saveSelectionToPlaylist(){const rows=selectedRows();if(!rows.length){toast("Select rows (Ctrl/Shift click) first, or right-click a row");return}const targets=[];for(const row of rows)for(let i=row.start;i<=row.end;i++)targets.push(state.items[i]);const existing=[...new Set(state.items.map(e=>e.playlist).filter(Boolean))];const hint=existing.length?`Existing playlists: ${existing.join(", ")}. New name = new group, existing name = append into it.`:"New playlist name — the selected items become its visible group.";const name=prompt(hint,existing.length?existing[0]:"New playlist");if(name===null||!name.trim())return;const groupName=name.trim(),playing=state.items[state.index],members=state.items.filter(e=>e.playlist===groupName);if(members.length){const seen=new Set(members),toInsert=targets.filter(t=>!seen.has(t));if(!toInsert.length){toast("Selection is already inside that playlist");return}state.items=state.items.filter(e=>!toInsert.includes(e));const last=state.items.lastIndexOf(members[members.length-1]);for(const it of toInsert)it.playlist=groupName;state.items.splice(last+1,0,...toInsert);state.index=playing?state.items.indexOf(playing):-1;state.expanded.add(groupName);renderQueue();toast(`${toInsert.length} item(s) sorted into “${groupName}”`);return}for(const it of targets)it.playlist=groupName;const removed=targets.filter(t=>state.items.includes(t));state.items=state.items.filter(t=>!targets.includes(t));state.items.push(...removed);state.index=playing?state.items.indexOf(playing):-1;state.expanded.add(groupName);renderQueue();toast(`Playlist “${groupName}” created with ${removed.length} item(s)`)}
function removeFromPlaylist(items){const playing=state.items[state.index];let count=0;for(const it of items)if(it?.playlist){it.playlist="";count++}if(!count){toast("No playlist entry selected");return}state.index=playing?state.items.indexOf(playing):-1;renderQueue();toast(`${count} item(s) removed from their playlist (stay in the queue)`)}
function showQueueMenu(event,item,groupName){event.preventDefault();const menu=document.createElement("div");menu.className="queue-menu";const add=(label,action)=>{const button=document.createElement("button");button.type="button";button.textContent=label;button.onclick=()=>{menu.remove();action()};menu.append(button)};if(groupName){add("▶ Play playlist",()=>playPlaylistGroup(groupName));if(state.expanded.has(groupName))add("Collapse playlist",()=>{state.expanded.delete(groupName);renderQueue()});else add("Expand playlist",()=>{state.expanded.add(groupName);renderQueue()});add("↑ Move playlist up",()=>movePlaylistGroup(groupName,-1));add("↓ Move playlist down",()=>movePlaylistGroup(groupName,1));add("Remove playlist from queue",()=>removePlaylistGroup(groupName));add("Remove ALL entries from playlist (keep in queue)",()=>removeFromPlaylist(state.items.filter(e=>e.playlist===groupName)))}else if(item){const index=state.items.indexOf(item);add("▶ Play",()=>playIndex(index));add("↑ Move up",()=>moveRows(-1));add("↓ Move down",()=>moveRows(1));add("Remove from queue",()=>removeRows());add("Save selection to playlist…",saveSelectionToPlaylist);if(item.playlist)add("Remove from playlist",()=>removeFromPlaylist([item]))}menu.style.left=event.clientX+"px";menu.style.top=event.clientY+"px";document.body.append(menu);const close=e=>{if(!menu.contains(e.target)){menu.remove();document.removeEventListener("click",close,true)}};setTimeout(()=>document.addEventListener("click",close,true),0)}
