async function hydrateYouTubeTitle(item,url){try{const response=await fetch("/api/youtube-title",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url})});const payload=await response.json();if(!response.ok||!payload.title)return;item.title=payload.title;if(payload.uploader)item.subtitle=payload.uploader;renderQueue();if(state.items[state.index]===item&&!item.transcodedUrl){$("#title").textContent=itemLabel(item)}}catch(error){}}
async function digestHex(buffer){const hash=await crypto.subtle.digest("SHA-256",buffer);return [...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,"0")).join("")}
