async function parseCasu(file){if(file.size>1024*1024*1024)throw Error("CASU file exceeds the 1 GiB browser verification limit");const header=new Uint8Array(await file.slice(0,100).arrayBuffer()),magic=new TextDecoder().decode(header.slice(0,8));if(magic==="CASUNAT1"){if(header.length<92)throw Error("CASUNAT1 header is truncated");const view=new DataView(header.buffer);const manifestLength=littleU64(view,12),payloadLength=littleU64(view,20),offset=92+manifestLength;if(manifestLength>64*1024*1024||offset+payloadLength!==file.size)throw Error("CASUNAT1 size or manifest limit does not match its header");const manifest=JSON.parse(await file.slice(92,offset).text());if(!manifest||typeof manifest!=="object"||Array.isArray(manifest)||!manifest.source||typeof manifest.source!=="object")throw Error("CASUNAT1 manifest is invalid");const name=manifest.source.filename||file.name.replace(/\.casu$/i,"");const payload=file.slice(offset,offset+payloadLength,mimeFor(name)),expected=[...header.slice(60,92)].map(v=>v.toString(16).padStart(2,"0")).join(""),actual=await digestHex(await payload.arrayBuffer());if(actual!==expected)throw Error("CASUNAT1 payload integrity failed");return {kind:"native1",manifest,payload}}if(magic==="CASUNAT2")return {kind:"native2",player:await CasuNative.open(file)};if(file.size>64*1024*1024)throw Error("CASU sidecar exceeds the 64 MiB browser limit");const manifest=JSON.parse(await file.text()),source=manifest?.source;if(!manifest||typeof manifest!=="object"||Array.isArray(manifest)||!source||typeof source.filename!=="string"||!source.filename||source.filename!==source.filename.replaceAll("\\","/").split("/").pop()||(source.sha256!==undefined&&!/^[0-9a-f]{64}$/i.test(source.sha256)))throw Error("CASU sidecar manifest is invalid");return {kind:"sidecar",manifest}}
